let lastTimestamp = 0;
        let intervals = [];
        const MAX_SAMPLES = 100;
        let stats = {
            max: 0,
            avg: 0,
            minDelay: Infinity,
            count: 0,
            sum: 0
        };
        const trackArea = document.getElementById('track-area');
        const currentHzEl = document.getElementById('current-hz');
        const maxHzEl = document.getElementById('max-hz');
        const avgHzEl = document.getElementById('avg-hz');
        const minDelayEl = document.getElementById('min-delay');
        const sampleCountEl = document.getElementById('sample-count');
        trackArea.addEventListener('mousemove', (e) => {
            const now = performance.now();
            if (lastTimestamp > 0) {
                const interval = now - lastTimestamp;
                // Ignore outliers (e.g. if the user stops moving or the window loses focus)
                if (interval < 200 && interval > 0) {
                    intervals.push(interval);
                    if (intervals.length > MAX_SAMPLES) intervals.shift();
                    const currentHz = Math.round(1000 / interval);
                    // Update current display
                    currentHzEl.innerText = currentHz;
                    // Update Global Stats
                    stats.count++;
                    stats.sum += currentHz;
                    if (currentHz > stats.max) stats.max = currentHz;
                    if (interval < stats.minDelay) stats.minDelay = interval;
                    updateStatsUI();
                }
            }
            lastTimestamp = now;
        });
        function updateStatsUI() {
            maxHzEl.innerText = stats.max;
            avgHzEl.innerText = Math.round(stats.sum / stats.count);
            minDelayEl.innerText = stats.minDelay.toFixed(2);
            sampleCountEl.innerText = stats.count;
        }
        function resetStats() {
            stats = { max: 0, avg: 0, minDelay: Infinity, count: 0, sum: 0 };
            intervals = [];
            lastTimestamp = 0;
            currentHzEl.innerText = "0";
            maxHzEl.innerText = "0";
            avgHzEl.innerText = "0";
            minDelayEl.innerText = "0.0";
            sampleCountEl.innerText = "0";
        }
        // Reset if mouse leaves area to prevent massive single-interval outliers
        trackArea.addEventListener('mouseleave', () => {
            lastTimestamp = 0;
            currentHzEl.innerText = "0";
        });
